{"name": "f_to_c", "code": "
def solve(inputs: dict) -> float:
    temp_f = inputs['TEMP_F']
    temp_c = (temp_f - 32) * 5 / 9
    return round(temp_c, 2)
"}

{"name": "solver", "code": "def solve(inputs: dict) -> float:
    p = inputs['PERCENTAGE_COMPLETED']
    t = inputs['TIME_SPENT']
    result = (t / p) * 100 - t
    return round(result, 2)
"}

{"name": "cost_per_unit", "code": "
def solve(inputs: dict) -> float:
    total_cost = inputs['MATERIAL_COST'] + inputs['LABOR_COST'] + inputs['OVERHEAD_COST']
    cost_per_unit = total_cost / inputs['TOTAL_UNITS']
    return round(cost_per_unit, 2)
"}
